import { memo, lazy, Suspense, useState } from 'react';

// Lazy load a heavy component
const HeavyDashboard = lazy(() => import('./HeavyDashboard'));

// Memoized component - only re-renders if props change
const UserCard = memo(function UserCard({ name, email }) {
  console.log('UserCard rendered:', name);
  return (
    <div>
      <h3>{name}</h3>
      <p>{email}</p>
    </div>
  );
});

function App() {
  const [showDashboard, setShowDashboard] = useState(false);
  const [count, setCount] = useState(0);

  return (
    <div>
      {/* UserCard won't re-render when count changes */}
      <UserCard name="Rahul" email="rahul@example.com" />
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>

      <button onClick={() => setShowDashboard(true)}>Load Dashboard</button>

      {showDashboard && (
        <Suspense fallback={<div>Loading Dashboard...</div>}>
          <HeavyDashboard />
        </Suspense>
      )}
    </div>
  );
}
